def lenOfVDiagonal(grid: List[List[int]]) -> int:
    n = len(grid)
    m = len(grid[0])
    # Directions ordered for clockwise turn logic: 
    # (1, 1) [DR] -> (1, -1) [DL] -> (-1, -1) [UL] -> (-1, 1) [UR] -> (1, 1)
    dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

    # memo[r][c][d] is the length of a straight segment starting at (r, c) 
    # moving in direction dirs[d], following the 2,0,2,0... pattern.
    memo = [[[0] * 4 for _ in range(m)] for _ in range(n)]

    # Fill memo bottom-up to avoid recursion limits and overhead
    for d in range(4):
        dr, dc = dirs[d]
        r_range = range(n - 1, -1, -1) if dr == -1 else range(n)
        c_range = range(m - 1, -1, -1) if dc == -1 else range(m)
        # To fill correctly, we need to iterate such that (r+dr, c+dc) is already processed.
        # For dr=1, r from n-1 down; for dr=-1, r from 0 up.
        # For dc=1, c from m-1 down; for dc=-1, c from 0 up.
