                    # The first step after '1' must be a '2'.
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2:
                        # We move in direction d_idx as long as possible.
                        curr_r, curr_c = nr, nc
                        dist = 1
                        while True:
