from typing import List
import bisect

def maxPathLength(coordinates: List[List[int]], k: int) -> int:
    target_x, target_y = coordinates[k]

    # 篩選出所有比目標點小的點 (左上方區域)
    left_side = []
    for x, y in coordinates:
        if x < target_x and y < target_y:
            left_side.append((x, y))

    # 篩選出所有比目標點大的點 (右下方區域)
    right_side = []
    for x, y in coordinates:
        if x > target_x and y > target_y:
            right_side.append((x, y))

    def get_lis_len(points: List[List[int]]) -> int:
        if not points:
            return 0
        # 先按 x 排序，若 x 相同則按 y 排序 (雖然此題點是唯一的)
        points.sort()
        # 使用標準 LIS 演算法 (O(N log N))
        tails = []
        for _, y in points:
            idx = bisect.bisect_left(tails, y)
            if idx < len(tails):
                tails[idx] = y
            else:
                tails.append(y)
        return len(tails)

    # 答案是 左側 LIS + 1 (目標點本身) + 右側 LIS
    return get_lis_len(left_side) + 1 + get_lis_len(right_side)
