from typing import List

def minValidStrings(words: List[str], target: str) -> int:
    # 建立所有可能的 prefix 集合 (使用 set 以獲得 O(1) 查詢)
    prefixes = set()
    for w in words:
        for i in range(1, len(w) + 1):
            prefixes.add(w[:i])

