    # dp[i] 代表組成 target[:i] 所需的最小字串數量
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(n):
        if dp[i] == float('inf'):
            continue
        # 從當前位置開始，嘗試匹配所有可能的 prefix
        # 因為我們只需要知道「是否存在」prefix，所以直接檢查子字串是否在 prefixes 中
        for j in range(i + 1, n + 1):
            if target[i:j] in prefixes:
                dp[j] = min(dp[j], dp[i] + 1)

    return dp[n] if dp[n] != float('inf') else -1
