    base_k = nums.count(k)

    max_gain = 0
    # For each possible value v that can be transformed into k by adding x
    # we want to find a subarray where (count of v) - (count of k) is max.
    # This is the Maximum Subarray Sum problem (Kadane's).
    for v in set(nums):
        if v == k:
