                    m2 = H_vals[i][k]
            f[i][j] = m1 if best_m != j else m2

    min_total = float('inf')
    for k in range(26):
        if H_vals[0][k] < min_total:
            min_total = H_vals[0][k]

    if min_total == float('inf'):
        return ""

    # To reconstruct the lexicographically smallest string:
    # We need to track if we are currently extending a block.
    res = []
    curr_j = -1
    current_cost_so_far = 0

    # Since H_vals[i][k] already includes the cost of character k at index i,
    # and f[i][j] is min(H_vals[i][k] for k != j), we can greedily pick k.
    for i in range(n):
        found = False
        for k in range(26):
            if k != curr_j:
                # Try starting a new block of character k at index i.
                if current_cost_so_far + H_vals[i][k] == min_total:
                    res.append(chr(97 + k))
                    current_cost_so_far += costs[i][k]
                    curr_j = k
                    found = True
                    break
            else:
                # We are extending the current block of character curr_j.
                # The cost to complete from here is H_vals[i][curr_j].
                if current_cost_so_far + (H_vals[i][curr_j] - costs[i][curr_j]) == min_total:
                    # Wait, the logic for "extending" in H_vals is:
                    # H_vals[i][k] = min(c3 + f[i+3][k], cost[i][k] + H_vals[i+1][k])
                    # If we are extending, it means we took the second term.
                    # Let's check if current state matches the "extension" path.
                    if costs[i][curr_j] + H_vals[i+1][curr_j] == H_vals[i][curr_j]:
                        res.append(chr(97 + curr_j))
                        current_cost_so_far += costs[i][curr_j]
                        found = True
                        break
        if not found:
            # This part should technically not be reached if min_total is correct.
            return ""

    return "".join(res)

```

這是一個經典的幾何切割問題。要滿足條件，我們需要找到兩個水平線（$y=k_1, y=k_2$）或兩個垂直線（$x=k_1, x=k_2$），使得這些線不會切斷任何矩形，且產生的三個區域各包含至少一個矩形。

最簡單的解法是檢查所有可能的「切割點」。對於水平切割，有效的 $y$ 座標一定是某個矩形的 `start_y` 或 `end_y`；同理垂直切割則是 `start_x` 或 `end_x`。

```python
from typing import List

def checkValidCuts(n: int, rectangles: List[List[int]]) -> bool:
    # 檢查水平或垂直方向是否可行
    return canCut(rectangles, is_horizontal=True) or canCut(rectangles, is_horizontal=False)

def canCut(rects: List[List[int]], is_horizontal: bool) -> bool:
    # 如果是水平切割，我們關注 y 座標 (index 1, 3)；否則關注 x 座標 (index 0, 2)
    # 提取所有可能的切割點（邊界）
    coords = []
    for r in rects:
        if is_horizontal:
            coords.append((r[1], r[3])) # (y_min, y_max)
        else:
            coords.append((r[0], r[2])) # (x_min, x_max)

    # 找出所有不被任何矩形佔用的切割點
    # 切割點必須在 [0, n] 之間，且不能落在任何矩形的內部（只能在邊界上）
    # 我們檢查所有的 y=k 或 x=k，其中 k 是所有矩形的邊界值
    possible_cuts = set()
    for start, end in coords:
        possible_cuts.add(start)
        possible_cuts.add(end)

    sorted_cuts = sorted([c for c in possible_cuts if 0 < c < n])

    # 過濾出真正的切割點：該座標不能處於任何矩形的內部 (start < cut < end)
    valid_cuts = []
    for cut in sorted_cuts:
        is_blocked = False
        for start, end in coords:
            if start < cut < end:
                is_blocked = True
                break
        if not is_blocked:
            valid_cuts.append(cut)

    # 檢查是否存在兩個切割點，使得三個區域各至少有一個矩形
    # 這裡的條件是：切開後的三個區塊中，每個區塊都要包含至少一個矩形
    # 因為題目說「每一個矩形都屬於恰好一個區塊」，我們只需要確保三個區塊都不為空即可
    if len(valid_cuts) < 2:
        return False

    # 為了效率，我們只需檢查連續的兩個切割點是否能滿足條件
    # 其實只要有兩個 valid_cuts，且它們將矩形分成三部分，就符合要求
    # 這裡簡單處理：如果存在兩個以上的有效切割點，通常代表可以切開。
    # 但要嚴謹一點，檢查區塊是否非空。由於題目保證矩形不重疊且數量 >= 3，
    # 只要我們選取的 cut 不會把任何一個矩形「切斷」，且區域分布正確即可。

    for i in range(len(valid_cuts) - 1):
        c1 = valid_cuts[i]
        c2 = valid_cuts[i+1]

        # 檢查三個區塊是否有矩形：
        # 區塊 1: < c1, 區塊 2: c1 <= x < c2, 區塊 3: >= c2
        has_1 = has_2 = has_3 = False
        for r in rects:
            if is_horizontal:
                low, high = r[1], r[3]
            else:
                low, high = r[0], r[2]

            if high <= c1:
                has_1 = True
            elif low >= c1 and high <= c2:
                has_2 = True
            elif low >= c2:
                has_3 = True

        if has_1 and has_2 and has_3:
            return True

    return False
```
